for(let col=0;col<n;col++){
  // pivot normalize
  let pivot=m[col][col]||1;
  for(let j=col;j<n;j++) m[col][j]=(m[col][j]/pivot);
  // eliminate others
  for(let row=0;row<n;row++) if(row!==col){
    let f=m[row][col];
    for(let j=col;j<n;j++) m[row][j]=m[row][j]-f*m[col][j];
  }
}
